    Store.undo();
    assert.strictEqual(la.groupId,gid,'ungroup undo: groupId restored');
    assert.strictEqual(lb.groupId,gid,'ungroup undo: groupId restored on lb');
    console.log('  ✓ group/ungroup undo/redo round-trips groupId correctly');
