    const kept = Shape.make('ellipse',{x:1,y:1,w:5,h:5});
    Store.applyRemote({op:'replace',after:[kept],afterWc:{[kept.id]:{x:{peer:'p',seq:1,ts:1}}},clock:{peer:'peer-rep',seq:2,ts:state._lastTs+1}});
