    state.shapes.length = 0;_invalidateGrid();state.wclock={};state._lastRep=null;state.seenOps=new Set();
    const a=Shape.make('rect',{x:0,y:0,w:10,h:10});
    const b=Shape.make('ellipse',{x:5,y:5,w:8,h:8});
