    let ok2=true;try{_undoWire({op:'ungroup',ids:['m1'],gid:'__proto__',before:[{id:'m1',groupId:'__proto__'}]})}catch(_){ok2=false}
    assert.ok(ok2,'undo-wire regroup survives a __proto__ groupId');
