    const r=Shape.make('rect',{id:'r1',x:0,y:0,w:10,h:10});state.shapes=[r];state.seenOps=new Set();_invalidateGrid();
    Net._onRecv({k:'op',peer:'p9',op:{op:'upd',id:'r1',after:forged,before:{x:0},clock:{peer:'p9',seq:1,ts:1}}},false);
