    delete l.elbow;l.curve=1;
    const cp=_connLabelXY(l);
    assert.ok(Number.isFinite(cp.x),'curve → ctrl anchor');
    delete l.curve;
    // ADR-0090: two vertices — label lands on the path's length-midpoint
