    state.shapes=[];_invalidateGrid();state.history=[];state.histIdx=-1;state.seq=0;state.seenOps=new Set();state.wclock={};state.selection=new Set();
    const txt49c=Shape.make('text',{x:0,y:0,text:'Hi'});
