    state.tool='select';
    const CP1=Shape.make('rect',{x:10,y:10,w:40,h:40});
    const CP2=Shape.make('rect',{x:100,y:10,w:40,h:40});
    Store.commit({op:'add',shape:CP1});Store.commit({op:'add',shape:CP2});
    const cp1=state.shapes[0];
