    for(const kk in toolKeys){
      fireKey(kk);
      assert.strictEqual(state.tool,toolKeys[kk],`'${kk}' picks the ${toolKeys[kk]} tool`);
    }
    fireKey('i');
    assert.strictEqual(state.tool,'eyedropper',"'i' picks the eyedropper (temporary)");
