    assert.strictEqual(byId(s.id).stroke,'#000','oversized clock.peer rejected');
    Store.applyRemote({op:'upd',id:s.id,before:{stroke:'#000'},after:{stroke:'red'},clock:{peer:'r1',seq:'snap:'.padEnd(200,'x'),ts:2}});
