  assert.ok(!E.byId('s1'),'delta dels removes a live shape');
  assert.ok(E.state.wclock.s1&&E.state.wclock.s1._del,'dels stamps the tomb clock');
  // (2) a newer _born outranks the incoming tomb → the shape survives
  const s2=_r('s2',5);
