  const A=Shape.make('rect',{x:0,y:0,w:10,h:10}),B=Shape.make('rect',{x:20,y:0,w:10,h:10}),R=Shape.make('rect',{x:40,y:0,w:10,h:10});
  E.Store.commit({op:'add',shape:A});
